"""Independent slow reference implementations (pure Python, no numpy)."""
from math import gcd


def ref_calib(profile):
    """All-pairs tight suprema via per-source Bellman-Ford. Returns
    (feasible, upper, negcycle_edge_list_or_None)."""
    K = profile['groups']
    jitter = profile['jitter_ps']
    meas = [tuple(m) for m in profile['measurements']]
    E = []
    for i, (a, b, lo, hi) in enumerate(meas):
        E.append((a, b, hi, 2 * i))
        E.append((b, a, -lo, 2 * i + 1))
    # feasibility
    dist = [0] * K
    for it in range(K + 1):
        ch = False
        for (u, v, w, eid) in E:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                ch = True
        if not ch:
            break
    else:
        ch = True
    if ch and it == K:
        # possible negative cycle: run one more full check
        neg = False
        for (u, v, w, eid) in E:
            if dist[u] + w < dist[v]:
                neg = True
        if neg:
            return (False, None, dist)
    # detect properly: run K+1 rounds and see if the (K+1)-th changed
    dist = [0] * K
    changed_last = False
    for it in range(K + 2):
        ch = False
        for (u, v, w, eid) in E:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                ch = True
        changed_last = ch
        if not ch:
            break
    if changed_last:
        return (False, None, dist)
    # all pairs
    upper = []
    for a in range(K):
        d = [None] * K
        d[a] = 0
        for it in range(K):
            ch = False
            for (u, v, w, eid) in E:
                if d[u] is not None and (d[v] is None or d[u] + w < d[v]):
                    d[v] = d[u] + w
                    ch = True
            if not ch:
                break
        upper.append(d)
    return (True, upper, None)


def _ceil_div(a, b):
    return -((-a) // b)


def ref_fabric(fab, g):
    """Independent construction of the periodic lineage graph.

    Returns (P, N, edges, anchors, vT, rho) where edges is a list of
    (u, v, cost, age_inc) over phase-device vertices u = p*N+i.
    """
    N = fab['n']; T = fab['interval_ns']; S = fab['slice_ns']; O = fab['offset_ns']
    Q = len(fab['slices'])
    P = (Q * S) // gcd(T, Q * S)
    links = fab['links']
    v = [[fab['drift_ppb'][i]] * P for i in range(N)]
    for (node, s, e, ex) in fab['heat']:
        for p in range(s, e):
            v[node][p] += ex
    anch = [[False] * P for _ in range(N)]
    for (node, s, e) in fab['anchors']:
        for p in range(s, e):
            anch[node][p] = True
    blk = [[False] * P for _ in range(len(links))]
    for (l, s, e) in fab['blackouts']:
        for p in range(s, e):
            blk[l][p] = True
    edges = []
    for p in range(P):
        # wait edges
        for i in range(N):
            edges.append((p * N + i, ((p + 1) % P) * N + i, v[i][p] * T, 1))
        q = ((O + p * T) // S) % Q
        rho = (O + p * T) % S
        for l in fab['slices'][q]:
            link = links[l]
            for dirc in (0, 1):
                if dirc == 0:
                    sn = link['ends'][0][0]; dn = link['ends'][1][0]
                    sc = link['ends'][0][2]; dc = link['ends'][1][2]
                    delay = link['delay_ns'][0]; defer = link['defer_rounds'][0]
                else:
                    sn = link['ends'][1][0]; dn = link['ends'][0][0]
                    sc = link['ends'][1][2]; dc = link['ends'][0][2]
                    delay = link['delay_ns'][1]; defer = link['defer_rounds'][1]
                # guard window
                if rho < g or rho + delay + g > S:
                    continue
                # blackout over the physical flight
                j = _ceil_div(delay, T)
                bad = False
                for u in range(j):
                    if blk[l][(p + u) % P]:
                        bad = True
                        break
                if bad:
                    continue
                # ageing
                m = j + defer
                partial = j * T - delay
                ageing = v[dn][(p + j - 1) % P] * partial
                for u in range(j, m):
                    ageing += v[dn][(p + u) % P] * T
                cost = ('HOP', sc, dc, ageing)
                edges.append((p * N + sn, ((p + d if False else (p + m) % P) * N + dn),
                              cost, m))
    return P, N, edges, anch, v


def ref_envelope(fab, g, hopfn):
    """Bellman-Ford label correcting over the periodic graph."""
    P, N, edges, anch, v = ref_fabric(fab, g)
    V = P * N
    B = [None] * V
    A = [None] * V
    for i in range(N):
        for p in range(P):
            if anch[i][p]:
                u = p * N + i
                B[u] = 0
                A[u] = 0
    einfo = []
    for (u, vv, cost, inc) in edges:
        if isinstance(cost, tuple):
            c = hopfn(cost[1], cost[2]) + cost[3]
        else:
            c = cost
        einfo.append((u, vv, c, inc))
    for _ in range(V + 2):
        ch = False
        for (u, vv, c, inc) in einfo:
            if B[u] is None:
                continue
            nb = B[u] + c
            na = A[u] + inc
            if B[vv] is None or nb < B[vv] or (nb == B[vv] and na < A[vv]):
                B[vv] = nb
                A[vv] = na
                ch = True
        if not ch:
            break
    else:
        raise AssertionError('reference did not converge')
    return P, N, B, A, anch, v
