import sys, random, json
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/tmp/t')
import exact, gen, ref

rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
bad = 0
for it in range(200):
    prof = gen.gen_profile(rng)
    fab = gen.gen_fabric(rng, prof)
    # --- calibration reference ---
    feas, upper, _ = ref.ref_calib(prof)
    c = exact.Calibration(prof)
    if feas != (c.status == 'ok'):
        print('CAL STATUS MISMATCH', prof); bad += 1; continue
    if feas:
        for a in range(prof['groups']):
            for b in range(prof['groups']):
                if upper[a][b] != c.upper[a][b]:
                    print('CAL VALUE MISMATCH', prof, a, b, upper[a][b], c.upper[a][b])
                    bad += 1
    else:
        # verify the returned cycle is a valid negative cycle
        K = prof['groups']; meas = [tuple(m) for m in prof['measurements']]
        if not exact._check_cycle(c.cycle, K, meas):
            print('BAD CYCLE', prof, c.cycle); bad += 1
        # also: an audit of the inconsistent artifact must accept it
        if not exact.audit(prof, fab, {'status': 'inconsistent', 'cycle': c.cycle})['valid']:
            print('AUDIT REJECTS OWN CYCLE'); bad += 1
        continue
    # --- plan / audit self consistency ---
    plan = exact.compile_plan(prof, fab)
    if plan['status'] != 'ok':
        print('PLAN STATUS'); bad += 1; continue
    res = exact.audit(prof, fab, plan)
    if not res['valid']:
        print('AUDIT REJECTS OWN PLAN')
        print(json.dumps(prof))
        print(json.dumps(fab))
        bad += 1
        continue
    # --- envelope reference ---
    calib = exact.Calibration(prof)
    F = exact.Fabric(fab, calib)
    for g in F.guards:
        P, N, B, A, anch, v = ref.ref_envelope(fab, g, calib.hop_as)
        if P != F.P:
            print('P MISMATCH'); bad += 1; continue
        env = F.envelope(g)
        for u in range(P * N):
            if (B[u] if B[u] is not None else None) != (env[0][u] if env[0][u] is not None else None):
                print('ENV BOUND MISMATCH', g, u, B[u], env[0][u])
                print(json.dumps(prof)); print(json.dumps(fab)); bad += 1; break
            if (A[u] if A[u] is not None else None) != (env[1][u] if env[1][u] is not None else None):
                print('ENV AGE MISMATCH', g, u, A[u], env[1][u])
                print(json.dumps(prof)); print(json.dumps(fab)); bad += 1; break
        else:
            continue
        break
print('bad =', bad)
